{"term": "سادية", "lang": "ar", "script": "arab", "romanization": "sādiyya", "category": "kink_paraphilia", "subcategory": "sadism", "concept": "sadism", "is_novel_concept": false, "register": "clinical", "crude": 40, "technical": 65, "recognition_pct_current": 58, "recognition_pct_peak": 58, "peak_year": null, "regional": null, "definition": "Sadism; sexual gratification derived from inflicting pain, humiliation, or suffering on a partner.", "english_term": "sadism", "english_translation_quality": "direct", "notes": "Arabized calque of the European psychological term, derived from the Marquis de Sade; known primarily in educated and psychology-literate circles; also used non-sexually in political and social commentary to mean generalized cruelty."}
{"term": "مازوشية", "lang": "ar", "script": "arab", "romanization": "māzūshiyya", "category": "kink_paraphilia", "subcategory": "masochism", "concept": "masochism", "is_novel_concept": false, "register": "clinical", "crude": 40, "technical": 65, "recognition_pct_current": 52, "recognition_pct_peak": 52, "peak_year": null, "regional": null, "definition": "Masochism; sexual gratification derived from experiencing pain, humiliation, or subjugation.", "english_term": "masochism", "english_translation_quality": "direct", "notes": "Arabized transliteration named after Leopold von Sacher-Masoch; less commonly known than سادية among general MSA speakers; primarily encountered in psychological literature and internet discourse; sometimes spelled ماسوشية in informal contexts."}
