{"term": "تقييد", "lang": "ar", "script": "arab", "romanization": "taqyīd", "category": "kink_paraphilia", "subcategory": "bondage", "concept": "bondage", "is_novel_concept": false, "register": "clinical", "crude": 25, "technical": 45, "recognition_pct_current": 88, "recognition_pct_peak": 88, "peak_year": null, "regional": null, "definition": "Physical restraint; in sexual/kink contexts, the erotic practice of restraining a partner with ropes, cuffs, or other means.", "english_term": "restraint / bondage", "english_translation_quality": "approximate", "notes": "General MSA word with broad non-sexual applications (legal confinement, restricted access, document registration); the BDSM meaning is secondary and understood only in kink-aware circles; crude score reflects erotic connotation rather than the base word, which is clinically neutral."}
